    ["QoL/Questing & Group"] = {
        { "quests", false, "Accepts, hands in and shares quests for you, and remembers the reward you saved for a quest. The Modifier skips them or triggers them, as Modifier Does says.", "Quests", false },
        { "quests", "Accept Quests", "Accepts a quest as soon as its text opens. Use the Modifier to read it first.", "Quests", false },
        { "quests", "Hand In Quests", "Hands in finished quests. A quest with a choice of rewards waits for you to pick one, unless you saved a reward for it. The Modifier skips it for that quest.", "Quests", false },
        { "quests", "Pick Quests From NPCs", "When an NPC offers several things, goes straight to a finished quest to hand in, or the first quest on offer. Works with the two options above.", "Quests", false },
        { "quests", "Saved Quest Rewards", "Alt-click a reward you can choose, in the quest log or at the quest giver, to save it for that quest in this profile; Alt-click it again to clear it. It is selected when you hand the quest in, and Hand In Quests takes it for you.", "Quests", false },
        { "quests", "Share Quests With Group", "While you are in a group, shares each quest you accept from an NPC with the others, if the quest can be shared. A quest someone shared with you is not shared again. The Modifier as you accept keeps it to yourself.", "Quests", false },
        { "quests", "Modifier", "The key that changes Accept Quests, Hand In Quests, Pick Quests From NPCs and sharing.", "Quests", false },
        { "quests", "Modifier Does", "Skips: the quest steps run unless you hold the key. Triggers: they run only while you hold it.", "Quests", false },
        { "Open Saved Rewards", false, "Saved Quest Rewards Every reward you saved for a quest, to look over and remove.", "Open Saved Rewards", false },
        { "gossip", false, "Picks the only option of a vendor, trainer, banker, auctioneer or stable master; nothing that costs money or moves you.", "NPC Gossip", false },
        { "gossip", "Modifier", "The key that changes Auto Gossip for that NPC.", "NPC Gossip", false },
        { "gossip", "Modifier Does", "Skips: it picks unless you hold the key. Triggers: it picks only while you hold it.", "NPC Gossip", false },
        { "groupButtons", false, "Invite, Disband and an invite button per friend, on your screen.", "On-Screen Buttons", false },
        { "groupButtons", "Growth Direction", "Which way the buttons line up from the first one.", "On-Screen Buttons", false },
        { "groupButtons", "Invite Buttons", "Pick the friends who get their own invite button.", "On-Screen Buttons", false },
        { "groupButtons", "Invite Target Button", "A button that invites your target.", "On-Screen Buttons", false },
        { "groupButtons", "Invite All Button", "A button that invites everyone on your invite buttons.", "On-Screen Buttons", false },
        { "groupButtons", "Disband Group", "Removes everyone from your group. Group leader only.", "On-Screen Buttons", false },
        { "groupButtons", "Button Width", false, "On-Screen Buttons", "Size" },
        { "groupButtons", "Button Height", false, "On-Screen Buttons", "Size" },
        { "groupButtons", "Font", false, "On-Screen Buttons", "Text" },
        { "groupButtons", "Font Size", false, "On-Screen Buttons", "Text" },
        { "groupButtons", "Outline", "A black outline round the text, in place of the soft shadow.", "On-Screen Buttons", "Text" },
        { "groupButtons", "Background", "A card behind the text, a soft dark fade, or nothing at all.", "On-Screen Buttons", "Background" },
        { "freeForAll", false, "Sets your party's loot to Free for All whenever you lead it.", "Always Free for All", false },
        { "playerHistory", false, "Remembers the players you group and chat with, stored only on your computer. Remembers the players you group and chat with, stored only on your computer. inspect panel history tab player tab notes", "Player History", false },
        { "playerHistory", "Record Chats", "Also keeps your last whispers and group chat lines with each player.", "Player History", false },
        { "playerHistory", "Forget After", "Forgets players you have not met for this many days.", "Player History", false },
        { "playerHistory", "Notes on Tooltips", "Shows your note and tag on a player's tooltip.", "Player History", false },
        { "playerHistory", "Clear History", "Deletes every player's recorded history, keeping your notes.", "Player History", false },
        { "playerHistory", "Clear Notes", "Deletes every note and tag you wrote on a player.", "Player History", false },
        { "finderRoles", false, "Role buttons on the Group Finder that show only the players and groups you want.", "Group Finder Roles", false },
        { "gamble", false, "Run Classic gambling sessions or a two-player Deathroll.", "Gamble", false },
        { "gamble", "Open Gamble", "Opens the Gamble window.", "Gamble", false },
    },
    ["QoL/XP"] = {
        { "xpBar", false, "Your level, experience and percentage on one bar, with the XP of completed quests and rested experience drawn past the fill. Replaces Blizzard's experience bar while it is on. Move it in the HUD Editor. Ctrl + right-click the bar to reset the session time and XP/Hour.", "XP Bar", false },
        { "xpBar", "Show at Max Level", "Keeps the bar up at max level, with your played time and session.", "XP Bar", "Show" },
        { "xpBar", "Keep Blizzard XP Bar", "Leaves Blizzard's experience bar up as well, so your action bars keep their spacing.", "XP Bar", "Show" },
        { "xpBar", "Show Texts On Mouseover", "Hides the texts until you hover the bar: the ones around it, or those on it too.", "XP Bar", "Show" },
        { "xpBar", "Incomplete Quests", "The XP of quests still in progress, as a faded segment after the completed ones.", "XP Bar", "Show" },
        { "xpBar", "Reset Session on Reload", "Starts the session time and XP/Hour again on a /reload. Off: a /reload carries on the session. A fresh login always starts a new one.", "XP Bar", "Show" },
        { "xpBar", "Width", false, "XP Bar", "Bar" },
        { "xpBar", "Height", false, "XP Bar", "Bar" },
        { "xpBar", "Bar Texture", false, "XP Bar", "Bar" },
        { "xpBar", "Background Opacity", false, "XP Bar", "Bar" },
        { "xpBar", "Shine", "A soft shine along the top of the bar and a glow where your XP ends.", "XP Bar", "Effects" },
        { "xpBar", "Notches", "Slim marks along the bottom of the bar at every 10%.", "XP Bar", "Effects" },
        { "xpBar", "Rested Stripes", "Fine diagonal stripes on the rested band.", "XP Bar", "Effects" },
        { "xpBar", "Quest XP Pulse", "The XP from a quest you hand in flashes on the bar and its amount rises off it.", "XP Bar", "Effects" },
        { "xpBar", "Ready to Level", "Your completed quests glow, with a star on the bar, when handing them in would level you.", "XP Bar", "Effects" },
        { "xpBar", "Level-Up Flash", "The bar flashes gold and drains back to empty when you level up.", "XP Bar", "Effects" },
        { "xpBar", "Hover Breakdown", "Hovering the bar shows your XP to level, quest and rested XP, and about how many kills are left.", "XP Bar", "Effects" },
        { "xpBar", "Font", false, "XP Bar", "Text" },
        { "xpBar", "Font Size", false, "XP Bar", "Text" },
        { "xpBar", "Outline", "A black outline round the text, in place of the soft shadow.", "XP Bar", "Text" },
        { "xpBar", "Fill Color", "Your experience. Its left end is a darker shade.", "XP Bar", "Colors" },
        { "xpBar", "Completed Quests Color", "The XP of completed quests, and their text.", "XP Bar", "Colors" },
        { "xpBar", "Incomplete Quests Color", "The XP of quests still in progress. By default the completed quests color, faded.", "XP Bar", "Colors" },
        { "xpBar", "Rested Color", "Rested experience, and its text.", "XP Bar", "Colors" },
        { "xpBar", "Background Color", "Behind the fill.", "XP Bar", "Colors" },
        { "xpBar", "Border Color", "The line round the bar.", "XP Bar", "Colors" },
        { "xpBar", "Left Text", "A text on the bar: click it on the preview to change it. Each text shows in one place on the bar: picking one shown elsewhere moves it there.", "XP Bar", "Text" },
        { "xpBar", "Center Text", "A text on the bar: click it on the preview to change it. Each text shows in one place on the bar: picking one shown elsewhere moves it there.", "XP Bar", "Text" },
        { "xpBar", "Right Text", "A text on the bar: click it on the preview to change it. Each text shows in one place on the bar: picking one shown elsewhere moves it there.", "XP Bar", "Text" },
        { "xpBar", "Top Left", "A text around the bar: click it on the preview to change it. Each text shows in one place around it: picking one shown elsewhere moves it there. Only Played Time and Session Time show at max level.", "XP Bar", "Around the Bar" },
