        { "xpBar", "Top Right", "A text around the bar: click it on the preview to change it. Each text shows in one place around it: picking one shown elsewhere moves it there. Only Played Time and Session Time show at max level.", "XP Bar", "Around the Bar" },
        { "xpBar", "Left", "A text around the bar: click it on the preview to change it. Each text shows in one place around it: picking one shown elsewhere moves it there. Only Played Time and Session Time show at max level.", "XP Bar", "Around the Bar" },
        { "xpBar", "Right", "A text around the bar: click it on the preview to change it. Each text shows in one place around it: picking one shown elsewhere moves it there. Only Played Time and Session Time show at max level.", "XP Bar", "Around the Bar" },
        { "xpBar", "Bottom Left", "A text around the bar: click it on the preview to change it. Each text shows in one place around it: picking one shown elsewhere moves it there. Only Played Time and Session Time show at max level.", "XP Bar", "Around the Bar" },
        { "xpBar", "Bottom", "A text around the bar: click it on the preview to change it. Each text shows in one place around it: picking one shown elsewhere moves it there. Only Played Time and Session Time show at max level.", "XP Bar", "Around the Bar" },
        { "xpBar", "Bottom Right", "A text around the bar: click it on the preview to change it. Each text shows in one place around it: picking one shown elsewhere moves it there. Only Played Time and Session Time show at max level.", "XP Bar", "Around the Bar" },
        { "xpTicker", false, "Your experience per hour on a small card, with time to level, played time, session length and recent level times. Hidden at max level. Hover it for Start, Pause and Reset (also /naowh xp start, pause or reset). Move it in the HUD Editor.", "XP per Hour", false },
        { "xpTicker", "Show Played Time", "Your total played time on this character, from level 1.", "XP per Hour", "Shown" },
        { "xpTicker", "Compare Characters", "Shows if you're ahead of or behind your other characters, and colors past levels by it.", "XP per Hour", "Shown" },
        { "xpTicker", "Show Ding Time", "How long the next level takes at your current rate.", "XP per Hour", "Shown" },
        { "xpTicker", "Show Time", "How long this session has run.", "XP per Hour", "Shown" },
        { "xpTicker", "Reset XP per Hour", "Starts the session again: its time, XP and rate. The XP Bar's XP/Hour starts again with it.", "XP per Hour", "Shown" },
        { "xpTicker", "Level History", "The level you are on as it runs, then completed levels, newest first.", "XP per Hour", "Level History" },
        { "xpTicker", "Levels Shown", "The most recent completed levels.", "XP per Hour", "Level History" },
        { "xpTicker", "Show Played at Ding", "Your played time when you reached each level, beside how long it took.", "XP per Hour", "Level History" },
