        { "xpTicker", "Hide While Resting", "Hidden in cities and inns.", "XP per Hour", "Visibility" },
        { "groupXP", false, "A bar per group member with their level and how far through it they are. Every member running Naowh Forever shares their experience, even with this off; anyone else shows their level. Updates wait until combat ends. Move it in the HUD Editor.", "Group XP", false },
        { "groupXP", "Show Yourself", "Your own bar among the group's.", "Group XP", false },
