        { "talentPoints", false, "Text on screen while you have talent points to spend. Hidden in combat. Move it in the HUD Editor.", "Talent Points", false },
        { "talentPoints", "Font", false, "Talent Points", "Text" },
        { "talentPoints", "Font Size", false, "Talent Points", "Text" },
        { "talentPoints", "Outline", "A black outline round the text, in place of the soft shadow.", "Talent Points", "Text" },
        { "talentPoints", "Background", "A card behind the text, a soft dark fade, or nothing at all.", "Talent Points", "Background" },
        { "talentPoints", "Apply Theme to Text Color", "The text in the theme's accent color instead of gold.", "Talent Points", "Colors" },
        { "trainer", false, "After visiting a trainer, a small window lists the abilities you just learned. Abilities from a tome or a quest show a moment after you learn them. Drag one from the window onto your bars.", "Trainer Popup", false },
        { "trainer", "Glow New Abilities", "Lights up the new abilities on your action bars until you use them.", "Trainer Popup", false },
        { "trainer", "Offer to Replace Lower Ranks", "Adds a button to the popup that swaps every lower rank on your bars for the highest rank you know. Keyboard and controller bars land in the same slot. Right-click a spell in the popup to keep its lower ranks, for downranking. Rank swaps only happen out of combat.", "Trainer Popup", false },
        { "trainer", "Check My Bars Now", "Looks for lower ranks on your bars now, as after a trainer visit (also /naowh ranks). Out of combat only.", "Trainer Popup", false },
        { "trainer", "Forget Kept Spells", "Forgets the spells you chose to keep at lower ranks, so the popup offers to swap them again.", "Trainer Popup", false },
        { "trainer", "Popup Position", "Puts the popup back where it first showed.", "Trainer Popup", false },
    },
    ["QoL/Loot & Items"] = {
        { "lootFeed", false, "Everything you loot pops up on screen with its icon, amount and value, stacking in your chosen direction and fading out. Hover a line for the item's tooltip. Move it in the HUD Editor.", "Loot Feed", false },
        { "lootFeed", "Show Money", false, "Loot Feed", "Lines" },
        { "lootFeed", "Show Quest Rewards", "A line for each quest you turn in, with the experience and money it gave. Reward items show as their own lines.", "Loot Feed", "Lines" },
        { "lootFeed", "Show Reputation", "A line for every reputation gain, from quests and kills alike.", "Loot Feed", "Lines" },
        { "lootFeed", "Show Kill Experience", "A line for the experience from each kill. Quest experience is on the quest's own line.", "Loot Feed", "Lines" },
        { "lootFeed", "Lowest Quality Shown", false, "Loot Feed", "Lines" },
        { "lootFeed", "Lines Shown", false, "Loot Feed", "Lines" },
        { "lootFeed", "Display Time", "How long each line stays before it fades.", "Loot Feed", "Lines" },
        { "lootFeed", "Growth Direction", "The newest line stays at the anchor; older lines stack in this direction.", "Loot Feed", "Lines" },
        { "lootFeed", "Show Item Value", "What each line is worth, in gold, silver and copper.", "Loot Feed", "Value" },
        { "lootFeed", "Price Source", "Auction (Naowh Scan) uses your last Scan Prices at the auction house; Auction (TSM) needs TradeSkillMaster. An item without an auction price counts at its vendor price.", "Loot Feed", "Value" },
        { "lootFeed", "Count Bank Items", "The number on each icon counts your bank as well as your bags.", "Loot Feed", "Value" },
        { "lootFeed", "Gold per Hour", "A running gold per hour beside the newest line, counting money and item value since your first loot this session.", "Loot Feed", "Value" },
        { "lootFeed", "Reset Gold per Hour", "Starts the gold per hour count again from your next loot.", "Loot Feed", "Value" },
        { "lootFeed", "Hide Blizzard Loot Window", "Takes everything the moment you loot, with Blizzard's loot window kept out of sight, so the feed is all you see. Works with or without the game's auto loot. Hold Shift while looting to get the window back. It also appears whenever something cannot be taken: a group roll, a locked item, or bags too full.", "Loot Feed", "Loot Window" },
        { "lootFeed", "Width", false, "Loot Feed", "Size" },
        { "lootFeed", "Line Height", "The icon grows and shrinks with it.", "Loot Feed", "Size" },
        { "lootFeed", "Spacing", "Space between lines. -1 lets neighbouring lines share one border instead of two side by side.", "Loot Feed", "Size" },
        { "lootFeed", "Font", false, "Loot Feed", "Text" },
        { "lootFeed", "Font Size", false, "Loot Feed", "Text" },
        { "lootFeed", "Outline", "A black outline round the text, in place of the soft shadow.", "Loot Feed", "Text" },
        { "lootFeed", "Style", "A dark or light fill and edge behind each line, or none.", "Loot Feed", "Background" },
        { "lootFeed", "Glow", "A soft glow beside each icon.", "Loot Feed", "Background" },
        { "lootTrade", false, "Looting, selling and repairing at vendors, auction house prices, and mail with your alts.", "Looting, Vendors, Mail & Auction House", false },
        { "lootTrade", "Type DELETE For You", "Types DELETE into the confirmation box for you, and names the item in the dialog as a link you can hover for its tooltip.", "Looting, Vendors, Mail & Auction House", "Looting" },
        { "lootTrade", "Faster Auto Loot", "Loots automatically without hiding the loot window. Hold Shift to loot manually.", "Looting, Vendors, Mail & Auction House", "Looting" },
        { "lootTrade", "Auto Repair", "Repairs all gear when you open a vendor who can.", "Looting, Vendors, Mail & Auction House", "Vendors" },
        { "lootTrade", "Auto Sell Junk", "Sells grey items when you open a vendor.", "Looting, Vendors, Mail & Auction House", "Vendors" },
        { "lootTrade", "Scan Prices Button", "A Scan Prices button on the auction house. It reads every listing and keeps the lowest buyout for each item, for this realm and faction. Blizzard allows one full scan every 15 minutes.", "Looting, Vendors, Mail & Auction House", "Auction Prices" },
        { "lootTrade", "Auction House Price", "Item tooltips show the item's price at your last auction house scan, for one of it, and how long ago that was. Scan with the Scan Prices button on the auction house.", "Looting, Vendors, Mail & Auction House", "Auction Prices" },
        { "lootTrade", "Alt Item Counts", "Item tooltips show how many your characters on this realm and faction hold in their bags, bank and mailbox. Each character is counted once you log in on it, and its bank once you open it.", "Looting, Vendors, Mail & Auction House", "Mail & Alts" },
        { "lootTrade", "Alts Button on Mail", "An Alts button beside the mailbox's Send tab lists your characters on this realm and faction with their level and gold. Pick one to fill the To box.", "Looting, Vendors, Mail & Auction House", "Mail & Alts" },
        { "lootTrade", "Quick Attach", "An Attach button beside the mailbox's Send tab: attach every trade good, one type of trade good, or your unbound gear in one click.", "Looting, Vendors, Mail & Auction House", "Mail & Alts" },
        { "lootTrade", "Mail Expiry Warning", "At login, names any of your characters with mail that expires within three days. It knows each character's mail from the last time it opened a mailbox.", "Looting, Vendors, Mail & Auction House", "Mail & Alts" },
        { "lootTrade", "Forget a Character", "Removes a deleted or transferred character from the counts and the Alts list.", "Looting, Vendors, Mail & Auction House", "Mail & Alts" },
        { "restock", false, "When you reach a city or inn, a flashing list in the middle of the screen of what you are short on. It stays up until you have what you need or leave. Move it in the HUD Editor.", "Restock Reminder", false },
        { "restock", "Class Reagents", "The reagents your known spells use, such as Arcane Powder, candles, seeds, Symbols of Kings and Flash Powder, matched to the highest rank you know.", "Restock Reminder", "Class Reagents" },
        { "restock", "Buy at Vendors", "At a vendor who sells them, tops your class reagents and ammo up to what you carry, and prints what it spent. Off by default: it spends gold for you.", "Restock Reminder", "Class Reagents" },
        { "restock", "Ammo", "Restocks equipped thrown weapons, or the arrows or shot in your ammo slot.", "Restock Reminder", "Ammo: Rogue, Warrior and Hunter" },
        { "restock", "Ammo to Carry", false, "Restock Reminder", "Ammo: Rogue, Warrior and Hunter" },
        { "restock", "Hunter Ammo Reminder", "Reminds you about your equipped ammo at its own amount, not the carry target.", "Restock Reminder", "Ammo: Hunter" },
        { "restock", "Remind Me When Ammo Falls To", "Reminds at or below this many equipped arrows or shot across all bag stacks.", "Restock Reminder", "Ammo: Hunter" },
        { "restock", "Food & Drink", "Counts food and drink separately across all stacks. Warriors and rogues do not need drink.", "Restock Reminder", "Food & Drink" },
        { "restock", "Food & Drink Below", false, "Restock Reminder", "Food & Drink" },
        { "restock", "Food Minimum Required Level", "Only count food and drink whose required level is within this range.", "Restock Reminder", "Food & Drink" },
        { "restock", "Food Maximum Required Level", "The same required-level filter applies to every stack, not each item separately.", "Restock Reminder", "Food & Drink" },
        { "restock", "Junk & Full Bags", "Reminds you to vendor junk, and when your bags are nearly full.", "Restock Reminder", "Bags" },
        { "restock", "Free Slots Below", false, "Restock Reminder", "Bags" },
        { "restock", "Font", false, "Restock Reminder", "Text" },
        { "restock", "Font Size", false, "Restock Reminder", "Text" },
        { "restock", "Outline", "A black outline round the text, in place of the soft shadow.", "Restock Reminder", "Text" },
        { "restock", "Background", "A card behind the text, a soft dark fade, or nothing at all.", "Restock Reminder", "Background" },
        { "bagSpace", false, "The cheapest items in your bags as a row of icons, cheapest first. Ctrl-click an icon to delete it, or click it to sell it while a vendor is open. Middle-click to ignore an item. Move it in the HUD Editor.", "Bag Space", false },
        { "bagSpace", "Items Shown", false, "Bag Space", "Offered" },
        { "bagSpace", "Highest Quality Offered", "Items above this quality are never offered.", "Bag Space", "Offered" },
        { "bagSpace", "Grey Items First", "Grey items come before everything else, whatever they sell for.", "Bag Space", "Offered" },
        { "bagSpace", "Outlevelled Food & Potions First", "Puts food, drink and potions 10 or more levels below you, marked with a clock, first.", "Bag Space", "Offered" },
        { "bagSpace", "Count Auction Prices", "An item worth more at the auction house than at a vendor is valued at its auction price, from your last Scan Prices or TradeSkillMaster.", "Bag Space", "Offered" },
        { "bagSpace", "Protect Needed Items", "Never offers reagents, ammo, quest items, keys, items in an equipment set or items on your BiS list.", "Bag Space", "Offered" },
        { "bagSpace", "Ignore List", "Items Bag Space never offers. Search for one, drag one in, or middle-click an icon on the row.", "Bag Space", "Offered" },
        { "bagSpace", "Only With Free Slots Below", "Shows the row only once your bags are this full. 0 shows it all the time.", "Bag Space", "Showing" },
        { "bagSpace", "Show When Bags Are Full", "An \"Inventory is full\" error brings the row up for 20 seconds, even with more free slots than the threshold above.", "Bag Space", "Showing" },
        { "bagSpace", "Show Free Slots", "Free bag slots out of your total, above the row. Hover it for each bag.", "Bag Space", "Showing" },
        { "bagSpace", "Offer to Stack", "A Stack button on the card when part-filled stacks of an item can be combined.", "Bag Space", "Showing" },
        { "bagSpace", "Show Prices", "What each stack is worth, in its largest coin, under its icon.", "Bag Space", "Showing" },
        { "bagSpace", "Pick Up Cheapest Item", "Puts the cheapest item on your cursor, to drop or sell.", "Bag Space", "Showing" },
        { "bagSpace", "Tooltip: Vendor Price", "What the whole stack sells for at a vendor, and each item's price.", "Bag Space", "Tooltips" },
        { "bagSpace", "Tooltip: Auction Price", "What the stack fetches at the auction house, from your last Scan Prices or TradeSkillMaster.", "Bag Space", "Tooltips" },
        { "bagSpace", "Tooltip: Delete Hint", "The Ctrl-click line, and Click to sell while a vendor is open.", "Bag Space", "Tooltips" },
        { "bagSpace", "Tooltip: Ignore Hint", "The Middle-click line.", "Bag Space", "Tooltips" },
        { "bagSpace", "Icon Size", false, "Bag Space", "Size" },
        { "bagSpace", "Direction", false, "Bag Space", "Size" },
        { "bagSpace", "Reverse Order", "Puts the cheapest item at the far end of the row instead of next to its anchor.", "Bag Space", "Size" },
        { "bagSpace", "Font", false, "Bag Space", "Text" },
        { "bagSpace", "Font Size", false, "Bag Space", "Text" },
        { "bagSpace", "Outline", "A black outline round the text, in place of the soft shadow.", "Bag Space", "Text" },
        { "bagSpace", "Background", "A card behind the text, a soft dark fade, or nothing at all.", "Bag Space", "Background" },
        { "bagSpace", "Hide in Combat", false, "Bag Space", "Visibility" },
        { "scrapMarker", false, "  /nf scrap nf scrap list alt-click ctrl-click mark scrap sell vendor", "Scrap Marker", false },
        { "scrapMarker", "Marking Modifier", "The key to hold as you click an item to mark it; Ctrl also opens the dressing room on gear.", "Scrap Marker", false },
        { "scrapMarker", "At the Vendor", "Sell your scrap when you open a vendor, ask you first, or do nothing.", "Scrap Marker", false },
        { "scrapMarker", "New Marks", "Whether a new mark counts on every character or only this one.", "Scrap Marker", false },
        { "scrapMarker", "Show Mark", "A scrap icon on the bag slot of each item marked as scrap.", "Scrap Marker", false },
        { "scrapMarker", "Protect BiS and Gear Sets", "Items on your BiS list or in a gear set are never scrap.", "Scrap Marker", false },
        { "scrapMarker", "Save Marks", "Keep a mark after the item leaves your bags, so the next one you loot is scrap too.", "Scrap Marker", false },
        { "scrapMarker", "Gear You Can't Wear", "Armour and weapons your class can never use count as scrap.", "Scrap Marker", "Rules" },
        { "scrapMarker", "Old Common Gear", "Grey and white gear far below your level counts as scrap.", "Scrap Marker", "Rules" },
        { "scrapMarker", "Levels Below You", "How far below your level gear has to be for Old Common Gear.", "Scrap Marker", "Rules" },
        { "Open Scrap List", false, "Scrap List Every item marked as scrap, to search, unmark, share or add to.", "Open Scrap List", false },
