        { "look", "Size", false, "Glimmer", false },
        { "look", "Brightness", false, "Glimmer", false },
        { "look", "Skill-Up Colors", "Color herbs and ore by your chance of a skill-up, red when your skill is too low.", "Glimmer", false },
