        { "look", "Quest Item Sparkle", "The game's own sparkle on every quest item, kept on through graphics presets.", "Glimmer", false },
        { "objects", false, "What lights up, each with its own effect and color if you like.", "Objects", false },
        { "objects", "Light Up Ore", "Mining veins and deposits.", "Objects", "Ore" },
        { "objects", "Effect", false, "Objects", "Ore" },
        { "objects", "Color", false, "Objects", "Ore" },
        { "objects", "Light Up Herbs", "Plants you can gather.", "Objects", "Herbs" },
        { "objects", "Effect", false, "Objects", "Herbs" },
        { "objects", "Color", false, "Objects", "Herbs" },
        { "objects", "Light Up Quest Objects", "Objects your quests need.", "Objects", "Quest Objects" },
        { "objects", "Effect", false, "Objects", "Quest Objects" },
        { "objects", "Color", false, "Objects", "Quest Objects" },
        { "objects", "Light Up Quest Givers", "NPCs with a quest to pick up or hand in. Glimmer shows their nameplate to light them up.", "Objects", "Quest Givers" },
        { "objects", "Effect", false, "Objects", "Quest Givers" },
        { "objects", "Color", false, "Objects", "Quest Givers" },
        { "objects", "Light Up Chests", "Chests, strongboxes and footlockers out in the world.", "Objects", "Chests" },
        { "objects", "Effect", false, "Objects", "Chests" },
        { "objects", "Color", false, "Objects", "Chests" },
        { "objects", "Light Up Fishing Bobber", "Your fishing bobber.", "Objects", "Fishing Bobber" },
        { "objects", "Effect", false, "Objects", "Fishing Bobber" },
        { "objects", "Color", false, "Objects", "Fishing Bobber" },
        { "hide", false, "Glimmer always rests in combat, since the game locks these settings there.", "When to Hide", false },
        { "hide", "In Dungeons and Raids", false, "When to Hide", false },
        { "hide", "On Nodes Your Skill Is Too Low For", "Leave them dark instead of grey.", "When to Hide", false },
        { "detect", false, "The one object the game would interact with is the one that lights up.", "Detection", false },
        { "detect", "Range", "How far away the game may pick an object to light up.", "Detection", false },
        { "detect", "Look For Objects", false, "Detection", false },
        { "detect", "Only Name What Glimmer Lights", "No soft target name on NPCs, mailboxes and doors.", "Detection", false },
        { "detect", "Interact Key", "Gathers, loots or uses the lit object once it is in reach.", "Detection", false },
        { "minimap", false, "Every spot herbs and ore grow near you, on the minimap, ringed in its skill-up color.", "Minimap Icons", false },
