        { "minimap", "Only My Professions", "Only herbs if you are an herbalist, only ore if you are a miner.", "Minimap Icons", false },
        { "gathered", false, "Glimmer notes every herb and vein you gather, so you can find them again.", "Gathered on the Map", false },
