    ["QoL/System"] = {
        { "performance", false, "NaowhQOL's recommended graphics, frame rate and network settings for a high, steady frame rate. Your own value is saved the first time each one changes, on this computer, and Restore All or turning a setting back off puts it back.", "Performance", false },
        { "performance", "Apply All Recommended", "Sets every recommended setting below. Your own value is saved first, so Restore All can put it back.", "Performance", "Recommended" },
        { "performance", "Restore All", "Puts back every setting this page has changed, to the value you had before.", "Performance", "Recommended" },
        { "performance", "Spell Queue Window", "How early you can press your next spell before the current one finishes, in milliseconds. 100 to 400 suits most: lower is more responsive, higher is more forgiving of latency. Melee around your ping + 100, ranged around your ping + 150.", "Performance", "Spell Queue" },
        { "performance", "Reload UI", "Some settings only take effect after a reload.", "Performance", "Spell Queue" },
        { "performance", "HDR", "High dynamic range, for an HDR monitor with HDR on in Windows.", "Performance", "HDR" },
        { "performance", "Peak Brightness", "Your monitor's peak brightness in nits, so the brightest parts are not clipped or dimmed.", "Performance", "HDR" },
        { "performance", "Render Scale", "Recommended: 100%, native resolution.|n|nOn sets it; off puts back the value you had before. Now: .", "Performance", "Render & Display" },
