        { "naowhScore", "On Player Tooltips", "A player's score on their tooltip. One running Naowh Forever shares theirs; anyone else's is read from their gear when you hover them, within inspect range and out of combat.", "Naowh Score", false },
        { "naowhScore", "Scan Your Group", "Reads your group members' gear in the background, one at a time while they are in range and out of combat, so their scores are ready before you hover them.", "Naowh Score", false },
        { "naowhScore", "Scan Players Nearby", "Reads the gear of the players around you in the background: your target, focus, mouseover and everyone whose nameplate shows, one at a time in inspect range and out of combat.", "Naowh Score", false },
        { "naowhScore", "Grade Against", "Grades a score by its share of the best: in the game, for their level, or Both.", "Naowh Score", false },
    },
    ["Training Planner/Settings"] = {
        { "Open Training Planner", false, " ", "Open Training Planner", false },
        { "onTheWay", false, "The Training Planner's help while you level: a toast when you level up with spells to train, and a panel beside your class trainer. The Training Planner's help while you level: a toast when you level up with spells to train, and a panel beside your class trainer. /nf trainer nf trainer waypoint class trainer", "On the Way", false },
        { "onTheWay", "Level-Up Toast", "When you level up with new spells to train, a toast says how many and what they cost, with buttons to open the planner and to put a waypoint on your nearest trainer. Move it in the HUD Editor.", "On the Way", false },
        { "onTheWay", "Panel at the Trainer", "Beside your class trainer, the spells you can learn now, ticked, with their total and Learn Selected. Untick one to leave it. Beside your class trainer, the spells you can learn now, ticked, with their total and Learn Selected. Untick one to leave it. put the new ranks on my bars swap ranks /nf ranks nf ranks", "On the Way", false },
        { "keys", false, "The key that opens the Training Planner.", "Key Binding", false },
        { "keys", "Open Training Planner", "Press this key to open the Training Planner, and again to close it.", "Key Binding", false },
        { "window", false, "The planner's own window, and a mini bar to leave up while you level. The planner's own window, and a mini bar to leave up while you level. right-click right click skip spell", "Window", false },
        { "window", "Mini Bar", "A small bar with your next trainer visit and your gold, to leave up while you level. Move it by dragging.", "Window", false },
        { "builds", false, "Save, make, share and follow talent builds in the planner's Builds tab. Save, make, share and follow talent builds in the planner's Builds tab. talents talent points follow import export share auto spend", "Talent Builds", false },
        { "builds", "Builds", "Opens the planner on its Builds tab.", "Talent Builds", false },
        { "builds", "Followed Build", "Stops spending your talent points on the build you follow.", "Talent Builds", false },
    },
    ["Journeys/Settings"] = {
        { "routes", false, "What a journey may use besides walking, flights and ships. What a journey may use besides walking, flights and ships. hearthstone teleport mage druid moonglade portal tram boat zeppelin", "Routes", false },
        { "routes", "Use the Hearthstone", "Start with your Hearthstone when it is ready and gets you there sooner.", "Routes", false },
        { "routes", "Hearthstone Must Save", "Keep your Hearthstone unless it saves at least this long.", "Routes", false },
        { "routes", "Use Class Teleports", "Start with a mage or druid teleport you know.", "Routes", false },
        { "routes", "Journeys to Tracked Quests", "Track a quest that is far away and Journeys plans the way there.", "Routes", false },
        { "routes", "Journeys to Map Pins", "Put a pin on the map yourself and Journeys plans the way there.", "Routes", false },
        { "routes", "Waypoint Only Where Steps End", "Put the game's waypoint on the dock, flight master or goal, not on every bend of the walk there.", "Routes", false },
        { "routes", "Learn Lifts as You Ride", "Notes the lifts you ride so they can be added to Journeys; /nf lifts lists them.", "Routes", false },
        { "routes", "Route on the Minimap", "Draw the journey on the minimap: the walk you are on, then the legs after it.", "Routes", false },
        { "routes", "Route on the World Map", "Draw the journey on the world map: the walk you are on, then each leg after it.", "Routes", false },
        { "card", false, "Every step of the journey you are on, with the time each takes.", "Journey Card", false },
        { "card", "Scale", false, "Journey Card", false },
        { "card", "Opacity", false, "Journey Card", false },
    },
    ["Discovery/Library Books"] = {
        { "Open Library Books", false, " ", "Open Library Books", false },
        { "tracker", false, "Pops up when you enter a zone with books you still need, with a waypoint for each and your progress toward the next reward, and stays while you are in that zone. The X closes it until you enter another. Move it in the HUD Editor.", "Tracker", false },
        { "tracker", "Always Show", "Keep the tracker up in every zone, with a dropdown of the zones where you still have books to find. Entering one selects it. The X on the tracker switches this off.", "Tracker", false },
        { "tracker", "Scale", "How big the tracker is.", "Tracker", false },
        { "tracker", "Opacity", "How solid the tracker is, in percent.", "Tracker", false },
        { "nearby", false, "Plays the map ping and names the book in chat when you come within range of one you still need. Once per book, until you walk away and come back.", "Nearby Alert", false },
        { "nearby", "Range", "How close a book has to be before it pings.", "Nearby Alert", false },
        { "nearby", "Ping Sound", "Plays the map ping when a book is near.", "Nearby Alert", false },
        { "nearby", "Chat Line", "Names the book in chat, with how far it is and where.", "Nearby Alert", false },
        { "waypoints", false, "What a waypoint from the Discovery window or the tracker does. What a waypoint from the Discovery window or the tracker does. sleeping bag steps", "Waypoints", false },
        { "waypoints", "Open the Map", "Also opens the world map on the waypoint, so you see where it is. Out of combat only.", "Waypoints", false },
        { "keys", false, "The key that opens Discovery's window.", "Key Binding", false },
        { "keys", "Open Discovery", "Press this key to open Discovery's window, and again to close it.", "Key Binding", false },
    },
