    ["Professions/Settings"] = {
        { "recipeWindow", false, "What Naowh's profession window adds to each recipe: the ones you have not learned yet, your next rank, and how many of each reagent you have. What Naowh's profession window adds to each recipe: the ones you have not learned yet, your next rank, and how many of each reagent you have. filter favorites favourites have materials skill-up skill up profitable boe bop bind on equip pickup star right-click right click track recipe create all bags full chat link shift ctrl click", "Recipe Window", false },
        { "recipeWindow", "Unlearned Recipes", "Lists the recipes you have not learned yet below your own. Click one to see the skill it needs, what it costs and where it comes from: the nearest trainers, the vendor selling its manual, or the mobs that drop it. Click a trainer or vendor to set a waypoint.", "Recipe Window", false },
        { "recipeWindow", "Next Rank Alert", "When a profession's skill is high enough for its next rank (Journeyman, Expert, Artisan), a banner under the skill bar and on its card in the overview says what it takes and who teaches it: the nearest trainer, book vendor or quest giver. Click Waypoint to mark them on your map. Reaching it also says so once in chat; /naowh profrank repeats that.", "Recipe Window", false },
        { "recipeWindow", "Reagents in Bags", "Adds a Bags column to the chosen recipe's reagents, showing how many of each you carry.", "Recipe Window", false },
        { "recipeWindow", "Reagents in Bank", "Adds a Bank column to the chosen recipe's reagents, showing how many of each are in your bank.", "Recipe Window", false },
        { "recipeWindow", "Train Favorites", "At a profession trainer who teaches any of your favourite recipes that you can learn now (star one before its name, or right-click it in the list), a window beside the trainer's lists them with their cost: Learn one, or Learn All.", "Recipe Window", false },
        { "craftOrders", false, "Opens another player's profession link in this window, to order crafts from them. Choose a recipe, set how many crafts, tick the materials you bring (or type how many), and Add to Order. The order on the right has a suggested tip per craft that you can change; Ask sends the crafter one message per craft with the amount, your materials and the tip: in party chat when they are in your party, else as a whisper. Prices and the tip need an auction house scan. Opens another player's profession link in this window, to order crafts from them. Choose a recipe, set how many crafts, tick the materials you bring (or type how many), and Add to Order. The order on the right has a suggested tip per craft that you can change; Ask sends the crafter one message per craft with the amount, your materials and the tip: in party chat when they are in your party, else as a whisper. Prices and the tip need an auction house scan. scan prices auction prices quality of life loot items", "Craft Orders", false },
        { "craftOrders", "Suggested Tip", "The share of what the items sell for that the suggested tip adds on top of paying back the crafter's own materials. At least 1s unless set to 0.", "Craft Orders", false },
        { "craftTimer", false, "Crafting several at once (Create All, or Create with a count) shows one bar for the whole batch, drawn like the Flight Timer: the recipe, how many are done and the time left on all of them. It sits where the Flight Timer is, as nobody crafts in flight: move it in the HUD Editor as the Flight Timer.", "Total Craft Timer", false },
        { "craftTimer", "Show Normal Cast Bar", "Keeps the normal cast bar visible alongside the total crafting timer.", "Total Craft Timer", false },
        { "craftTimer", "Font", false, "Total Craft Timer", "Text" },
        { "craftTimer", "Font Size", false, "Total Craft Timer", "Text" },
        { "craftTimer", "Outline", "A black outline round the text, in place of the soft shadow.", "Total Craft Timer", "Text" },
        { "craftTimer", "Bar Texture", false, "Total Craft Timer", "Bar" },
        { "craftTimer", "Background Opacity", false, "Total Craft Timer", "Bar" },
        { "buying", false, "Prices, profit and buying the reagents of the chosen recipe, at the auction house or a vendor.", "Buying and Selling", false },
        { "buying", "Crafting Profit", "Once you have scanned the auction house (Scan Prices), the chosen recipe shows what its reagents cost to buy and what the item sells for, and the profit after the 5% auction house cut. Each reagent is priced at its cheapest: a vendor's price once you have seen a vendor sell it, else the lowest buyout at your last scan. Uncheck a reagent you already have to leave it out of the cost, for every recipe that uses it. Hover the lines for the breakdown. Once you have scanned the auction house (Scan Prices), the chosen recipe shows what its reagents cost to buy and what the item sells for, and the profit after the 5% auction house cut. Each reagent is priced at its cheapest: a vendor's price once you have seen a vendor sell it, else the lowest buyout at your last scan. Uncheck a reagent you already have to leave it out of the cost, for every recipe that uses it. Hover the lines for the breakdown. auction prices quality of life loot items", "Buying and Selling", "Prices" },
        { "buying", "Profit in Recipe List", "Also shows each recipe's profit at the right of its row in the list, green or red. Recipes whose profit is not known show none.", "Buying and Selling", "Prices" },
        { "buying", "Recipe Availability Marks", "Shows small markers on recipe rows when the result is in your bags or bank, or the recipe is already on the Shopping List. Hover a marker for its exact count. Equipped items do not count as bag contents.", "Buying and Selling", "Prices" },
        { "buying", "Show ROI", "Shows the selected recipe's profit as a percentage of the materials' cost, under its profit.", "Buying and Selling", "Return on Investment" },
        { "buying", "Grey Below", "ROI below this percentage is grey.", "Buying and Selling", "Return on Investment" },
        { "buying", "Green From", "ROI from this percentage is green; the range below it is yellow.", "Buying and Selling", "Return on Investment" },
        { "buying", "Shift-Click Searches AH", "While the auction house is open, Shift-click a recipe or a reagent to search the auction house for the item: what the recipe makes, or the reagent. While you type in chat, Shift-click still links it.", "Buying and Selling", "Auction House" },
        { "buying", "Search AH Button", "While the auction house is open, a Search AH button next to the chosen recipe's name searches it for the item the recipe makes. Unlearned recipes also get Search Recipe, for the pattern, plans or manual that teaches it. Recipes that make no item, such as enchants, get no Search AH.", "Buying and Selling", "Auction House" },
        { "buying", "Buy on AH", "While the auction house is open, a Buy button under the chosen recipe's reagents buys the materials for as many crafts as you set beside it: every checked reagent that vendors do not sell. Each one shows its price first and is only bought when you click Confirm.", "Buying and Selling", "Auction House" },
        { "buying", "Search Favorites AH", "At the auction house, a window beside it lists the patterns, plans and manuals of your favourite recipes that you have not learned or bought, with what they cost now. Buy finds the cheapest and asks before Accept buys it.", "Buying and Selling", "Auction House" },
        { "buying", "Manual Favorite Scans", "Adds Scan, Pause and Resume controls instead of searching every favourite automatically.", "Buying and Selling", "Auction House" },
        { "buying", "Shopping List", "Adds \"- [1] + Add to List\" under a recipe's reagents: the materials Buy on AH would buy for that many crafts go on a shopping list, from anywhere. At the auction house the list shows beside it: Check Prices looks each one up and warns in red when one is well above your last scan, then Buy All goes through the list one material at a time, each bought only when you confirm its final price. A material you can make for less from its parts, such as a bar from ore, has its parts bought instead.", "Buying and Selling", "Auction House" },
        { "buying", "Crafts with Vendor Buys", "Adds a second, orange number next to each recipe: how many you could make after buying the reagents vendors sell, such as Weak Flux or Coarse Thread. The recipe's reagents then say how many of each to buy.", "Buying and Selling", "Vendors" },
        { "buying", "Buy at Vendor", "While a merchant is open, a Buy button under the chosen recipe's reagents buys from them, in one click, every checked reagent they sell, such as Coarse Thread or Weak Flux, for as many crafts as you set beside it. The total cost shows beside the button; hover Buy for each reagent.", "Buying and Selling", "Vendors" },
        { "gather", false, "Shows an icon on screen while you know Find Herbs, Find Minerals or Find Fish but are tracking none of them. Click it to start tracking: left-click for the first, right-click for the second, middle-click for the third. Hover it to see which is which. Hidden in combat. Move it in the HUD Editor.", "Tracking Reminder", false },
        { "gather", "Show in Dungeons and Raids", "Also reminds you inside instances. Off by default: few have herbs or ore.", "Tracking Reminder", false },
        { "gather", "Include Find Fish", "Counts Find Fish as a tracking to remind you of, once you have learned it. Turn off if you only track fish now and then.", "Tracking Reminder", false },
        { "gather", "Icon Size", "How big the reminder icon is.", "Tracking Reminder", "Size" },
        { "gather", "Font", false, "Tracking Reminder", "Text" },
        { "gather", "Font Size", false, "Tracking Reminder", "Text" },
        { "gather", "Outline", "A black outline round the text, in place of the soft shadow.", "Tracking Reminder", "Text" },
        { "disenchant", false, "With Enchanting open, a Disenchant button at the top of the window opens a window of every item in your bags you can disenchant: green, blue and purple weapons and armor (or type /naowh disenchant). Right-click an item to keep that one copy, or Shift-right-click to keep every copy of it, on any character, until you right-click it again. Disenchant All disenchants the rest one by one, one item per click, as the game asks a click for every disenchant. An item the game will not take (skill too low) is skipped until you reload. Closes when combat starts.", "Disenchant Window", false },
    },
    ["Macros/Settings"] = {
