        { "food", false, "NF Food uses the best food and drink in your bags. Switch it on in Kept Current.", "Food Macro", false },
        { "food", "Food Only", "NF Food uses only food, and NF Drink is the one for drink.", "Food Macro", false },
        { "extra", false, "Add your own lines to the bag macros. They are kept after the item, whatever is in your bags.", "Extra Lines", false },
        { "extra", "NF Health", "Lines added after the macro's own. Write \\n between lines, as in /use [@mouseover,help][]Holy Light\\n/cqs. Left out, with a message, if the macro would pass 255 characters or the lines run a script.", "Extra Lines", false },
