        { "extra", "NF Mana", "Lines added after the macro's own. Write \\n between lines, as in /use [@mouseover,help][]Holy Light\\n/cqs. Left out, with a message, if the macro would pass 255 characters or the lines run a script.", "Extra Lines", false },
        { "extra", "NF Food", "Lines added after the macro's own. Write \\n between lines, as in /use [@mouseover,help][]Holy Light\\n/cqs. Left out, with a message, if the macro would pass 255 characters or the lines run a script.", "Extra Lines", false },
        { "extra", "NF Drink", "Lines added after the macro's own. Write \\n between lines, as in /use [@mouseover,help][]Holy Light\\n/cqs. Left out, with a message, if the macro would pass 255 characters or the lines run a script.", "Extra Lines", false },
        { "extra", "NF Bandage", "Lines added after the macro's own. Write \\n between lines, as in /use [@mouseover,help][]Holy Light\\n/cqs. Left out, with a message, if the macro would pass 255 characters or the lines run a script.", "Extra Lines", false },
        { "focus", false, "NF Focus focuses your mouseover, or your target. Switch it on in Kept Current.", "Focus Macro", false },
