    ["Action Bars/Settings"] = {
        { "Open Action Bars", false, " ", "Open Action Bars", false },
        { "importing", false, "What a saved set brings back when you import it. Sets are saved and imported from the Action Bars window, out of combat. What a saved set brings back when you import it. Sets are saved and imported from the Action Bars window, out of combat. /nf bars nf bars /nfbars nfbars save restore import test delete list /nf ab nf ab", "Importing", false },
        { "importing", "Highest Rank", "Imports the highest rank you know of each spell instead of the rank that was saved. When off, a rank you no longer have still falls back to your highest.", "Importing", false },
        { "importing", "Import Macros", "Makes the set's macros that this character does not have. A macro you already have, by name and text or by text alone, is used as it is: never copied twice or changed.", "Importing", false },
        { "importing", "Import Keybinds", "Binds every key the set has bound. Keys the set leaves free keep what they do here.", "Importing", false },
        { "importing", "Fill In As You Learn", "A spell an import could not place because you do not know it yet goes into its saved slot when you learn it, unless you have put something else there.", "Importing", false },
        { "importing", "Import on New Character", "For your class: imports this set once on a new character, at level 1 with no experience yet.", "Importing", false },
        { "importing", "Save on Logout", "When you log out, the set this character saved last is saved again with your bars, macros and keybinds as they are.", "Importing", false },
    },
    ["AuraBuffs/Settings"] = {
        { "Open AuraBuffs", false, " ", "Open AuraBuffs", false },
        { "buffs", false, "A row of icons for missing food, flask, elixir and scroll buffs, your own class buff, and class buffs missing in your group. Out of combat only: the game keeps your buffs from addons in combat, so the icons keep what they showed. Hover one to pick a carried item to use. Move them in the HUD Editor.", "Buffs & Consumables", false },
        { "buffs", "Show In", false, "Buffs & Consumables", "Consumables" },
