    ["Threat Meter/Settings"] = {
        { "meter", false, "Threat on your target or focus for everyone in your group, one bar each. A friendly target shows the enemy it is fighting. Scroll the meter for more entries; unlock its window to drag and resize it, or place it in the HUD Editor.", "Meter", false },
        { "meter", "Focus Tracking", "Adds target and focus switching to the meter's title bar.", "Meter", "Tracking" },
        { "meter", "Track", false, "Meter", "Tracking" },
